// ABO Admin · Pages — front-end only, static data.
//
// Scope (per scope rule §3):
//   - No fetch / XHR / WebSockets. No localStorage / IndexedDB.
//   - The 6 sample pages are generated by
//     resources/views/admin/pages/index.blade.php
//     (TODO(backend): replace with API data) and serialised into
//     one <script type="application/json"> tag. Every reference
//     here reads from that one dataset.
//
// The script wires seven interactive things and nothing else:
//   1. The list of pages (search + status filter + keyboard nav)
//   2. The editor (title EN/AR switch, slug, content toolbar with
//      EN/AR switch, contact details, SEO collapsible + counters,
//      settings switches, system-page warnings, dirty dot)
//   3. Add mode (clears the editor, focuses the first field)
//   4. Save (visual only, toasts "Saved (demo)", updates the row)
//   5. Preview modal (renders the current page in a store-like frame)
//   6. Delete confirm modal (custom pages only; system delete is
//      disabled with a coral note)
//   7. The single shared toast + slide-over on tablet / mobile

/* eslint-disable no-console */

(function () {
    'use strict';

    // ─── Shortcuts ────────────────────────────────────────────

    const $  = (sel, root) => (root || document).querySelector(sel);
    const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));

    const root = document.querySelector('.abo-admin-page') || document.body;

    // ─── Data ─────────────────────────────────────────────────

    function readJSON(id, fallback) {
        const el = document.getElementById(id);
        try { return JSON.parse(el ? el.textContent : '') || fallback; }
        catch (err) { console.error('[pages] failed to parse', id, err); return fallback; }
    }

    let PAGES = readJSON('abo-admin-pages-data', []);

    if (!root || PAGES.length === 0) {
        console.warn('[pages] no dataset found; leaving shell rendered.');
        return;
    }

    // ─── State ────────────────────────────────────────────────

    const state = {
        list:    { search: '', status: '' },
        editor:  { id: null, mode: 'idle', dirty: false, lang: { title: 'en', content: 'en' } },
        preview: { open: false },
        delete:  { open: false, id: null },
    };

    // ─── Today / relative time ───────────────────────────────

    const NOW = new Date('2026-10-16T10:00:00');

    function relative(iso) {
        if (!iso) return '';
        const t = new Date(iso);
        const diff = (NOW - t) / 1000;
        if (diff < 60)        return 'just now';
        if (diff < 3600) {
            const m = Math.round(diff / 60);
            return m + (m === 1 ? ' minute ago' : ' minutes ago');
        }
        if (diff < 86400) {
            const h = Math.round(diff / 3600);
            return h + (h === 1 ? ' hour ago' : ' hours ago');
        }
        if (diff < 86400 * 7) {
            const d = Math.round(diff / 86400);
            return d + (d === 1 ? ' day ago' : ' days ago');
        }
        if (diff < 86400 * 30) {
            const w = Math.round(diff / (86400 * 7));
            return w + (w === 1 ? ' week ago' : ' weeks ago');
        }
        const mo = Math.round(diff / (86400 * 30));
        return mo + (mo === 1 ? ' month ago' : ' months ago');
    }

    function initials(title) {
        const t = String(title || '').trim();
        if (!t) return '·';
        return t.slice(0, 1).toUpperCase();
    }

    function escapeHTML(s) {
        return String(s).replace(/[&<>"']/g, (c) => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
        }[c]));
    }

    function slugify(text) {
        return String(text || '')
            .toLowerCase()
            .trim()
            .replace(/[^\w\s-]/g, '')
            .replace(/[\s_-]+/g, '-')
            .replace(/^-+|-+$/g, '')
            .slice(0, 80);
    }

    // ─── Path helpers ─────────────────────────────────────────

    function getAt(obj, path) {
        return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
    }
    function setAt(obj, path, val) {
        const parts = path.split('.');
        let cur = obj;
        for (let i = 0; i < parts.length - 1; i++) {
            if (cur[parts[i]] == null) cur[parts[i]] = {};
            cur = cur[parts[i]];
        }
        cur[parts[parts.length - 1]] = val;
    }

    // ─── Toast ────────────────────────────────────────────────

    let toastTimer;
    function toast(text) {
        const wrap = $('[data-abo-admin-pages-toast]');
        const txt  = $('[data-abo-admin-pages-toast-text]', wrap);
        if (!wrap) return;
        txt.textContent = text;
        wrap.hidden = false;
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => { wrap.hidden = true; }, 2400);
    }

    // ─── List filtering + render ─────────────────────────────

    function filteredPages() {
        const f = state.list;
        const q = f.search.trim().toLowerCase();
        return PAGES.filter((p) => {
            if (f.status && p.status !== f.status) return false;
            if (q) {
                const hay = (p.title.en + ' ' + p.title.ar + ' ' + p.slug).toLowerCase();
                if (hay.indexOf(q) === -1) return false;
            }
            return true;
        });
    }

    function rowHTML(p) {
        const title  = p.title.en || 'Untitled';
        const ar     = p.title.ar || '';
        const path   = '/' + (p.slug || '');
        const type   = p.type;     // system | custom
        const status = p.status;   // published | draft
        const upd    = relative(p.updated);
        const typeCls = type === 'custom' ? ' abo-admin-pages__type--custom' : '';
        return ''
            + '<button type="button" class="abo-admin-pages__row" '
            +   'role="option" '
            +   'aria-selected="' + (state.editor.id === p.id ? 'true' : 'false') + '" '
            +   'data-abo-admin-pages-row="' + escapeHTML(p.id) + '">'
            +   '<span class="abo-admin-pages__row-icon" aria-hidden="true">' + escapeHTML(initials(title)) + '</span>'
            +   '<span class="abo-admin-pages__row-text">'
            +     '<span class="abo-admin-pages__row-title">' + escapeHTML(title)
            +       (ar ? ' <span style="color:var(--abo-admin-gray);font-weight:500;font-size:0.78rem;">· ' + escapeHTML(ar) + '</span>' : '')
            +     '</span>'
            +     '<span class="abo-admin-pages__row-path">' + escapeHTML(path) + '</span>'
            +   '</span>'
            +   '<span class="abo-admin-pages__row-meta">'
            +     '<span class="abo-admin-pages__type' + typeCls + '">' + escapeHTML(type) + '</span>'
            +     '<span class="abo-admin-pages__status abo-admin-pages__status--' + status + '">' + escapeHTML(status) + '</span>'
            +     '<span class="abo-admin-pages__row-updated">Updated ' + escapeHTML(upd) + '</span>'
            +   '</span>'
            + '</button>';
    }

    function renderList() {
        const list = $('[data-abo-admin-pages-list]');
        const nores = $('[data-abo-admin-pages-state="noresults"]');
        const empty = $('[data-abo-admin-pages-state="empty"]');
        if (!list) return;
        const items = filteredPages();
        list.innerHTML = items.map(rowHTML).join('');

        if (nores) nores.hidden = items.length > 0 || (PAGES.length === 0);
        if (empty) empty.hidden = PAGES.length !== 0;
        const count = $('[data-abo-admin-pages-result-count]');
        if (count) count.textContent = items.length + (items.length === 1 ? ' page' : ' pages');
    }

    function updateListClear() {
        // No-op for now; we use a "CLEAR FILTERS" button in the no-results state.
    }

    function wireListToolbar() {
        const search = $('[data-abo-admin-pages-search]');
        const status = $('[data-abo-admin-pages-filter="status"]');
        const clear  = $('[data-abo-admin-pages-clear]');
        if (search) search.addEventListener('input', () => {
            state.list.search = search.value;
            renderList();
        });
        if (status) status.addEventListener('change', () => {
            state.list.status = status.value;
            renderList();
        });
        if (clear) clear.addEventListener('click', () => {
            state.list = { search: '', status: '' };
            if (search) search.value = '';
            if (status) status.value = '';
            renderList();
        });
    }

    function wireListClicks() {
        const list = $('[data-abo-admin-pages-list]');
        if (!list) return;
        list.addEventListener('click', (ev) => {
            const row = ev.target.closest('[data-abo-admin-pages-row]');
            if (!row) return;
            selectPage(row.getAttribute('data-abo-admin-pages-row'));
        });
        list.addEventListener('keydown', (ev) => {
            if (ev.key !== 'ArrowDown' && ev.key !== 'ArrowUp' && ev.key !== 'Home' && ev.key !== 'End') return;
            const rows = $$('[data-abo-admin-pages-row]', list);
            if (rows.length === 0) return;
            const active = document.activeElement && document.activeElement.closest('[data-abo-admin-pages-row]');
            let idx = active ? rows.indexOf(active) : -1;
            if (ev.key === 'ArrowDown') idx = Math.min(rows.length - 1, idx + 1);
            else if (ev.key === 'ArrowUp') idx = Math.max(0, idx - 1);
            else if (ev.key === 'Home') idx = 0;
            else if (ev.key === 'End') idx = rows.length - 1;
            if (idx < 0) idx = 0;
            ev.preventDefault();
            rows[idx].focus();
        });
    }

    // ─── Editor: open, populate, close ───────────────────────

    const editorEl       = $('[data-abo-admin-pages-editor]');
    const editorPlaceholder = $('[data-abo-admin-pages-editor-placeholder]');
    const editorPane      = $('[data-abo-admin-pages-editor-pane]');
    const editorTitle     = $('[data-abo-admin-pages-editor-title]');
    const editorMode      = $('[data-abo-admin-pages-editor-mode]');
    const editorDirty     = $('[data-abo-admin-pages-editor-dirty]');
    const editorCloseBtn  = $('[data-abo-admin-pages-editor-close]');
    const deleteBtn       = $('[data-abo-admin-pages-action="delete"]');
    const systemWarning   = $('[data-abo-admin-pages-system-warning]');
    const contactBlock    = $('[data-abo-admin-pages-contact-block]');
    const seoBody         = $('[data-abo-admin-pages-seo-body]');
    const seoToggle       = $('[data-abo-admin-pages-seo-toggle]');
    const seoToggleText   = $('[data-abo-admin-pages-seo-toggle-text]');
    const slugLock        = $('[data-abo-admin-pages-slug-lock]');
    const slugInput       = $('[data-abo-admin-pages-slug]');
    const slugNote        = $('[data-abo-admin-pages-slug-note]');

    function showEditor() {
        if (editorEl)       editorEl.hidden = false;
        if (editorPlaceholder) editorPlaceholder.hidden = true;
        if (editorPane)     editorPane.classList.add('is-open');
    }

    function hideEditor() {
        if (editorEl)       editorEl.hidden = true;
        if (editorPlaceholder) editorPlaceholder.hidden = false;
        if (editorPane)     editorPane.classList.remove('is-open');
        state.editor.id = null;
        state.editor.mode = 'idle';
    }

    function setDirty(d) {
        state.editor.dirty = d;
        if (editorDirty) editorDirty.hidden = !d;
    }

    function applyLang(lang, scope) {
        // scope: 'title' | 'content'
        // Toggle the visible input/area for the selected language.
        const inputs = $$(scope === 'title'
            ? '[data-abo-admin-pages-title-lang]'
            : '[data-abo-admin-pages-content-lang]');
        inputs.forEach((el) => {
            const v = el.getAttribute(scope === 'title' ? 'data-abo-admin-pages-title-lang' : 'data-abo-admin-pages-content-lang');
            el.hidden = v !== lang;
        });
        // Update the switch buttons.
        $$('[data-abo-admin-pages-lang="' + scope + '"]').forEach((b) => {
            const active = b.getAttribute('data-abo-admin-pages-lang-value') === lang;
            b.classList.toggle('is-active', active);
            b.setAttribute('aria-selected', active ? 'true' : 'false');
        });
        state.editor.lang[scope] = lang;
    }

    function setSystemWarning(page) {
        if (!systemWarning) return;
        if (page && page.type === 'system' && page.status === 'draft') {
            systemWarning.textContent = 'This page is linked from the store footer and checkout. Unpublishing it will break those links.';
            systemWarning.hidden = false;
        } else {
            systemWarning.hidden = true;
        }
    }

    function setDeleteEnabled(page) {
        if (!deleteBtn) return;
        const isSystem = page && page.type === 'system';
        deleteBtn.disabled = !!isSystem;
        if (isSystem) {
            deleteBtn.setAttribute('aria-disabled', 'true');
        } else {
            deleteBtn.removeAttribute('aria-disabled');
        }
    }

    function applyContactBlock(page) {
        if (!contactBlock) return;
        const isContact = page && page.id === 'contact-us';
        contactBlock.hidden = !isContact;
    }

    function applySlugLock(page) {
        if (!slugInput || !slugLock || !slugNote) return;
        const isSystem = page && page.type === 'system';
        slugInput.readOnly = !!isSystem;
        slugInput.classList.toggle('abo-admin-pages__field-input--slug', true);
        slugLock.hidden = !isSystem;
        if (isSystem) {
            slugNote.textContent = 'System page URL is fixed.';
        } else {
            slugNote.textContent = 'Auto-generated from the English title. You can edit it.';
        }
    }

    function selectPage(id) {
        const p = PAGES.find((x) => x.id === id);
        if (!p) return;
        // If we're in add mode or another page, drop the buffer.
        if (state.editor.id && state.editor.id !== id && state.editor.dirty) {
            if (!confirm('You have unsaved changes. Discard them?')) {
                return;
            }
        }
        state.editor.id = id;
        state.editor.mode = 'edit';
        populateEditor(p);
        showEditor();
        renderList();
    }

    function startAdd() {
        // Create a transient new page (custom draft).
        const id = 'new-' + Date.now();
        const draft = {
            id: id,
            title: { en: '', ar: '' },
            slug: '',
            type: 'custom',
            status: 'draft',
            showInFooter: false,
            updated: new Date().toISOString(),
            meta: {
                en: { title: '', description: '' },
                ar: { title: '', description: '' },
            },
            content: { en: '', ar: '' },
        };
        PAGES.push(draft);
        state.editor.id = id;
        state.editor.mode = 'add';
        populateEditor(draft);
        showEditor();
        renderList();
        // Focus the first title input.
        setTimeout(() => {
            const t = $('[data-abo-admin-pages-title-lang="en"]');
            if (t) t.focus();
        }, 50);
    }

    function populateEditor(p) {
        if (!p) return;
        // Editor head
        if (editorMode)  editorMode.textContent = state.editor.mode === 'add' ? 'NEW PAGE' : 'EDIT PAGE';
        if (editorTitle) editorTitle.textContent = (p.title.en || p.title.ar || (state.editor.mode === 'add' ? 'Untitled page' : 'Untitled'));

        // Title EN/AR
        const tEn = $('[data-abo-admin-pages-title-lang="en"]');
        const tAr = $('[data-abo-admin-pages-title-lang="ar"]');
        if (tEn) tEn.value = p.title.en || '';
        if (tAr) tAr.value = p.title.ar || '';
        applyLang('en', 'title');

        // Slug
        if (slugInput) slugInput.value = p.slug || '';
        applySlugLock(p);

        // Content EN/AR
        const cEn = $('[data-abo-admin-pages-content-lang="en"]');
        const cAr = $('[data-abo-admin-pages-content-lang="ar"]');
        if (cEn) cEn.innerHTML = p.content.en || '';
        if (cAr) cAr.innerHTML = p.content.ar || '';
        applyLang('en', 'content');

        // Contact details
        applyContactBlock(p);
        if (p.contact) {
            const fields = ['email','phone','whatsapp','address','hours','instagram','facebook','tiktok'];
            fields.forEach((f) => {
                const el = $('[data-abo-admin-pages-field="contact.' + f + '"]');
                if (el) el.value = p.contact[f] || '';
            });
        }

        // SEO (English counters only for the demo)
        const metaTitleEl = $('[data-abo-admin-pages-field="meta.en.title"]');
        const metaDescEl  = $('[data-abo-admin-pages-field="meta.en.description"]');
        if (metaTitleEl) metaTitleEl.value = (p.meta && p.meta.en && p.meta.en.title) || '';
        if (metaDescEl)  metaDescEl.value  = (p.meta && p.meta.en && p.meta.en.description) || '';
        updateAllCounters();

        // Settings: Published, Show in footer
        const statusEl = $('[data-abo-admin-pages-field="status"]');
        if (statusEl) statusEl.checked = p.status === 'published';
        const showInFooterEl = $('[data-abo-admin-pages-field="showInFooter"]');
        if (showInFooterEl) showInFooterEl.checked = !!p.showInFooter;
        setSystemWarning(p);
        setDeleteEnabled(p);

        setDirty(false);
    }

    // ─── Char counters (SEO) ─────────────────────────────────

    function updateAllCounters() {
        $$('[data-abo-admin-pages-counter-input]').forEach((el) => {
            const key = el.getAttribute('data-abo-admin-pages-counter-input');
            const max = Number(el.getAttribute('data-abo-admin-pages-counter-max') || 0);
            const counterEl = $('[data-abo-admin-pages-counter="' + key + '"]');
            if (!counterEl) return;
            const len = (el.value || '').length;
            counterEl.textContent = len + ' / ' + max;
            counterEl.classList.toggle('abo-admin-pages__counter--coral', len > max);
        });
    }

    // ─── Field wiring (title / slug / content / contact / SEO / settings) ───

    function wireFields() {
        // Title EN
        const tEn = $('[data-abo-admin-pages-title-lang="en"]');
        if (tEn) tEn.addEventListener('input', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.title.en = tEn.value;
            if (editorTitle) editorTitle.textContent = tEn.value || (p.title.ar || (state.editor.mode === 'add' ? 'Untitled page' : 'Untitled'));
            // Auto-update slug for custom pages, until the user edits the slug manually.
            if (p.type === 'custom' && slugInput && !slugInput.dataset.userEdited) {
                const s = slugify(tEn.value);
                slugInput.value = s;
                p.slug = s;
            }
            setDirty(true);
            renderList();
        });

        // Title AR
        const tAr = $('[data-abo-admin-pages-title-lang="ar"]');
        if (tAr) tAr.addEventListener('input', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.title.ar = tAr.value;
            setDirty(true);
            renderList();
        });

        // Slug
        if (slugInput) {
            slugInput.addEventListener('input', () => {
                const p = PAGES.find((x) => x.id === state.editor.id);
                if (!p) return;
                p.slug = slugify(slugInput.value);
                slugInput.value = p.slug;
                if (p.type === 'custom') slugInput.dataset.userEdited = '1';
                setDirty(true);
                renderList();
            });
        }

        // Content EN / AR (input bubbles from contenteditable)
        const cEn = $('[data-abo-admin-pages-content-lang="en"]');
        if (cEn) cEn.addEventListener('input', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.content.en = cEn.innerHTML;
            setDirty(true);
        });
        const cAr = $('[data-abo-admin-pages-content-lang="ar"]');
        if (cAr) cAr.addEventListener('input', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.content.ar = cAr.innerHTML;
            setDirty(true);
        });

        // Contact details
        ['email','phone','whatsapp','address','hours','instagram','facebook','tiktok'].forEach((f) => {
            const el = $('[data-abo-admin-pages-field="contact.' + f + '"]');
            if (el) el.addEventListener('input', () => {
                const p = PAGES.find((x) => x.id === state.editor.id);
                if (!p) return;
                if (!p.contact) p.contact = {};
                p.contact[f] = el.value;
                setDirty(true);
            });
        });

        // SEO
        const metaTitle = $('[data-abo-admin-pages-field="meta.en.title"]');
        const metaDesc  = $('[data-abo-admin-pages-field="meta.en.description"]');
        if (metaTitle) metaTitle.addEventListener('input', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            if (!p.meta) p.meta = { en: {}, ar: {} };
            if (!p.meta.en) p.meta.en = {};
            p.meta.en.title = metaTitle.value;
            updateAllCounters();
            setDirty(true);
        });
        if (metaDesc) metaDesc.addEventListener('input', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            if (!p.meta) p.meta = { en: {}, ar: {} };
            if (!p.meta.en) p.meta.en = {};
            p.meta.en.description = metaDesc.value;
            updateAllCounters();
            setDirty(true);
        });

        // Settings: Published (bool → published/draft), Show in footer
        const statusEl = $('[data-abo-admin-pages-field="status"]');
        if (statusEl) statusEl.addEventListener('change', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.status = statusEl.checked ? 'published' : 'draft';
            setSystemWarning(p);
            setDirty(true);
            renderList();
        });
        const showInFooterEl = $('[data-abo-admin-pages-field="showInFooter"]');
        if (showInFooterEl) showInFooterEl.addEventListener('change', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.showInFooter = !!showInFooterEl.checked;
            setDirty(true);
        });

        // Language switches
        $$('[data-abo-admin-pages-lang="title"]').forEach((b) => {
            b.addEventListener('click', () => applyLang(b.getAttribute('data-abo-admin-pages-lang-value'), 'title'));
        });
        $$('[data-abo-admin-pages-lang="content"]').forEach((b) => {
            b.addEventListener('click', () => applyLang(b.getAttribute('data-abo-admin-pages-lang-value'), 'content'));
        });

        // SEO collapse
        if (seoToggle) seoToggle.addEventListener('click', () => {
            const open = seoToggle.getAttribute('aria-expanded') === 'true';
            const next = !open;
            seoToggle.setAttribute('aria-expanded', next ? 'true' : 'false');
            if (seoBody) seoBody.hidden = !next;
            if (seoToggleText) seoToggleText.textContent = next ? 'Hide' : 'Show';
        });

        // Content toolbar
        $$('[data-abo-admin-pages-tb]').forEach((btn) => {
            btn.addEventListener('mousedown', (e) => {
                // Prevent losing the selection.
                e.preventDefault();
            });
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                const cmd = btn.getAttribute('data-abo-admin-pages-tb');
                const arg = btn.getAttribute('data-abo-admin-pages-tb-arg');
                if (cmd === 'createLink') {
                    const url = prompt('Link URL (https://…)');
                    if (!url) return;
                    document.execCommand('createLink', false, url);
                } else if (cmd === 'formatBlock' && arg) {
                    document.execCommand('formatBlock', false, arg);
                } else {
                    document.execCommand(cmd, false, null);
                }
                // Sync the editor content back to the model.
                const activeLang = state.editor.lang.content;
                const cEl = $('[data-abo-admin-pages-content-lang="' + activeLang + '"]');
                if (cEl) {
                    const p = PAGES.find((x) => x.id === state.editor.id);
                    if (p) {
                        p.content[activeLang] = cEl.innerHTML;
                        setDirty(true);
                    }
                }
            });
        });
    }

    // ─── Add / Save / Delete / Preview ────────────────────────

    function wireActions() {
        // Add (header)
        const addBtn = $('[data-abo-admin-pages-action="add"]');
        if (addBtn) addBtn.addEventListener('click', startAdd);
        // Add (empty state)
        const addEmpty = $('[data-abo-admin-pages-action="add-empty"]');
        if (addEmpty) addEmpty.addEventListener('click', startAdd);

        // Save
        const saveBtn = $('[data-abo-admin-pages-action="save"]');
        if (saveBtn) saveBtn.addEventListener('click', () => {
            const p = PAGES.find((x) => x.id === state.editor.id);
            if (!p) return;
            p.updated = new Date().toISOString();
            setDirty(false);
            renderList();
            toast('Saved (demo)');
        });

        // Delete
        if (deleteBtn) deleteBtn.addEventListener('click', () => {
            if (deleteBtn.disabled) return;
            openDelete(state.editor.id);
        });

        // Preview
        const previewBtn = $('[data-abo-admin-pages-action="preview"]');
        if (previewBtn) previewBtn.addEventListener('click', openPreview);

        // Close (slide-over on mobile)
        if (editorCloseBtn) editorCloseBtn.addEventListener('click', hideEditor);
    }

    // ─── Preview modal ────────────────────────────────────────

    const previewModal  = $('[data-abo-admin-pages-preview]');
    const previewFrame  = $('[data-abo-admin-pages-preview-frame]');

    function openPreview() {
        const p = PAGES.find((x) => x.id === state.editor.id);
        if (!p || !previewModal || !previewFrame) return;
        const lang = state.editor.lang.content;
        const title = (lang === 'ar' ? p.title.ar : p.title.en) || 'Untitled';
        const body  = (lang === 'ar' ? p.content.ar : p.content.en) || '';
        const isRtl = lang === 'ar';
        previewFrame.className = 'abo-admin-pages__preview-frame' + (isRtl ? ' abo-admin-pages__preview-frame--rtl' : '');
        let html = '<h2>' + escapeHTML(title) + '</h2>';
        html += '<p class="abo-admin-pages__preview-frame-meta">URL: /' + escapeHTML(p.slug || '') + ' · ' + escapeHTML(p.status) + '</p>';
        html += body;
        if (p.id === 'contact-us' && p.contact) {
            html += '<h2>Contact details</h2>';
            html += '<p><strong>Email:</strong> ' + escapeHTML(p.contact.email || '') + '</p>';
            html += '<p><strong>Phone:</strong> ' + escapeHTML(p.contact.phone || '') + '</p>';
            html += '<p><strong>WhatsApp:</strong> ' + escapeHTML(p.contact.whatsapp || '') + '</p>';
            html += '<p><strong>Address:</strong><br>' + escapeHTML(p.contact.address || '').replace(/\n/g, '<br>') + '</p>';
            html += '<p><strong>Hours:</strong> ' + escapeHTML(p.contact.hours || '') + '</p>';
        }
        previewFrame.innerHTML = html;
        previewModal.hidden = false;
    }

    function closePreview() {
        if (previewModal) previewModal.hidden = true;
    }

    function wirePreview() {
        if (!previewModal) return;
        $$('[data-abo-admin-pages-preview-close]', previewModal).forEach((b) => {
            b.addEventListener('click', closePreview);
        });
        document.addEventListener('keydown', (ev) => {
            if (previewModal && !previewModal.hidden && ev.key === 'Escape') {
                ev.preventDefault();
                closePreview();
            }
        });
    }

    // ─── Delete confirm modal ────────────────────────────────

    const deleteModal = $('[data-abo-admin-pages-delete]');
    const deleteBody  = $('[data-abo-admin-pages-delete-body]');

    function openDelete(id) {
        const p = PAGES.find((x) => x.id === id);
        if (!p || !deleteModal) return;
        state.delete.id = id;
        const name = p.title.en || p.title.ar || 'this page';
        if (deleteBody) deleteBody.textContent = '"' + name + '" will be removed from the store. This action cannot be undone.';
        deleteModal.hidden = false;
        setTimeout(() => {
            const cancel = deleteModal.querySelector('[data-abo-admin-pages-delete-close]');
            if (cancel) cancel.focus();
        }, 30);
    }

    function closeDelete() {
        if (deleteModal) deleteModal.hidden = true;
        state.delete.id = null;
    }

    function confirmDelete() {
        if (!state.delete.id) return;
        const idx = PAGES.findIndex((x) => x.id === state.delete.id);
        if (idx >= 0) PAGES.splice(idx, 1);
        closeDelete();
        hideEditor();
        renderList();
        toast('Deleted (demo)');
    }

    function wireDelete() {
        if (!deleteModal) return;
        $$('[data-abo-admin-pages-delete-close]', deleteModal).forEach((b) => {
            b.addEventListener('click', closeDelete);
        });
        const confirm = $('[data-abo-admin-pages-delete-confirm]');
        if (confirm) confirm.addEventListener('click', confirmDelete);
        document.addEventListener('keydown', (ev) => {
            if (deleteModal && !deleteModal.hidden && ev.key === 'Escape') {
                ev.preventDefault();
                closeDelete();
            }
        });
    }

    // ─── Boot ─────────────────────────────────────────────────

    function boot() {
        wireListToolbar();
        wireListClicks();
        wireFields();
        wireActions();
        wirePreview();
        wireDelete();
        // Hide skeletons.
        const load = $('[data-abo-admin-pages-state="loading"]');
        if (load) load.hidden = true;
        renderList();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        boot();
    }
})();
